import{_ as t,o as n,c as i,a3 as r}from"./chunks/framework.BlfGB29P.js";const c=JSON.parse('{"title":"Home Assistant Card Editor","description":"","frontmatter":{},"headers":[],"relativePath":"projects/atlas-plugins/homeassistant-card-editor.md","filePath":"projects/atlas-plugins/homeassistant-card-editor.md","lastUpdated":1792852622000}'),a={name:"projects/atlas-plugins/homeassistant-card-editor.md"};function s(d,e,o,l,u,h){return n(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="home-assistant-card-editor" tabindex="-1">Home Assistant Card Editor <a class="header-anchor" href="#home-assistant-card-editor" aria-label="Permalink to &quot;Home Assistant Card Editor&quot;">​</a></h1><p>Der Home Assistant Card Editor ist das erste offizielle ATLAS-Referenz-Plugin. Er zeigt, wie Plugin-Lebenszyklus, Discovery, Administration, Hub-Anzeige, Import/Export und Paketbau zusammen funktionieren.</p><h2 id="aufgabe" tabindex="-1">Aufgabe <a class="header-anchor" href="#aufgabe" aria-label="Permalink to &quot;Aufgabe&quot;">​</a></h2><p>Stand 16.10.2026: Referenz-Plugin <strong>0.2.0-alpha.108</strong> in App <strong>0.1.312</strong>. Es wird mit ATLAS aktualisiert, nicht durch Ersetzen als externes Plugin. Gemeinsame Projekte und die vollständigen HACS-Card-Export-/Import-Anleitungen stehen im <a href="./../atlas/card-editor">Editor-Leitfaden</a> und unter <a href="./../atlas/frontend">App/Runtime-Projekte</a>.</p><p>Produktentscheidung vom 13.10.2026: Der Editor bleibt ausschließlich Expert. Simple-Modus und Umschalter werden nicht wieder eingeführt. Unterstützte ältere Projektimporte bleiben kompatibel.</p><p>Ab HA-App <strong>0.1.292</strong> entfällt auch die Startmodus-Auswahl in der HA-App-Konfiguration und in Administration. Alte gespeicherte Simple-Werte werden als Expert übernommen; Zugangsdaten und andere Einstellungen bleiben erhalten.</p><p>Das Plugin stellt einen Editor für Home-Assistant-Cards bereit. Es unterstützt den Expert-Workflow, Entity-Auswahl, Ressourcenprüfung, YAML/JSON-Import, HACS-nahe Bundle-Exporte und mehrsprachige Card-Pakete. Der frühere sichtbare Simple-Modus wurde entfernt; der Editor startet direkt im Expert-Workflow.</p><p>Im Expert-Workflow bleibt das Hintergrundraster quadratisch. Die Anzahl der Spalten wird oben über einen horizontalen Slider gesteuert, die Anzahl der Zeilen links über einen vertikalen Slider. Ein eigener Zoom-Slider verändert nur die Zellgröße und skaliert Breite und Höhe gemeinsam. Die frühere Streckfunktion ist damit in Feldanzahl und Zoom getrennt.</p><h2 id="card-liste-auf-tablets" tabindex="-1">Card-Liste auf Tablets <a class="header-anchor" href="#card-liste-auf-tablets" aria-label="Permalink to &quot;Card-Liste auf Tablets&quot;">​</a></h2><p>Ab HA-App <strong>0.1.290</strong> stehen bei einer Editorbreite von 521 bis 1180 Pixeln zwei Cards nebeneinander in einem scrollbaren Fenster. Die Höhe passt sich an die erste Card-Zeile an und bleibt auf kleinen Bildschirmhöhen begrenzt. Weitere Cards sind durch Scrollen erreichbar. Die Aktionsbuttons über der Liste stehen ebenfalls in zwei gleich breiten Spalten. Auf schmalen Smartphones bleibt eine Spalte; die Desktop-Seitenleiste bleibt unverändert. Entscheidend ist die Breite des eingebetteten Editors, nicht der Gerätename. Bestehende Projekte, Favoriten und Einstellungen bleiben erhalten.</p><h2 id="mobile-raster-und-titelbedienung" tabindex="-1">Mobile Raster- und Titelbedienung <a class="header-anchor" href="#mobile-raster-und-titelbedienung" aria-label="Permalink to &quot;Mobile Raster- und Titelbedienung&quot;">​</a></h2><p>Ab HA-App <strong>0.1.291</strong> ist „Raster &amp; Zoom“ bei Editorbreiten bis 1180 Pixeln standardmäßig eingeklappt. Ein Antippen öffnet die X-, Y- und Zoom-Slider; Ein- und Ausklappen verändert keine Werte oder Cards. Beim Wechsel auf eine Desktopbreite werden die Slider wieder direkt angezeigt.</p><p>Auf Tablets stehen Titelfeld, „Titel übernehmen“ und „Entitätsname nutzen“ in einer Reihe. Auf schmalen Smartphones steht das Titelfeld über den beiden gleich breiten Buttons. Diese Anordnung gilt in DE/EN/FR.</p><h2 id="live-verbindung-bei-großen-entitatskatalogen" tabindex="-1">Live-Verbindung bei großen Entitätskatalogen <a class="header-anchor" href="#live-verbindung-bei-großen-entitatskatalogen" aria-label="Permalink to &quot;Live-Verbindung bei großen Entitätskatalogen&quot;">​</a></h2><p>Ab HA-App <strong>0.1.293</strong> verarbeitet ATLAS Entitätsabfragen und Live-Ereignisse in der Reihenfolge ihres Empfangs. Eine noch laufende Abfrage kann dadurch ein danach empfangenes Ereignis nicht mehr mit alten Snapshot-Werten überholen. Nach einem Verbindungsabbruch werden wartende Nachrichten der alten Verbindung ignoriert; schlägt der neue Socket fehl, wird dessen Fehlerstatus angezeigt. Gespeicherte Cards, Positionen und Zugangsdaten werden dabei nicht verändert.</p><h2 id="extension-points" tabindex="-1">Extension Points <a class="header-anchor" href="#extension-points" aria-label="Permalink to &quot;Extension Points&quot;">​</a></h2><p>Der Editor nutzt aktuell diese ATLAS-Extension-Points:</p><ul><li><code>homeassistant.card-editor</code></li><li><code>homeassistant.card-target</code></li><li><code>homeassistant.entity-picker</code></li><li><code>homeassistant.exporter</code></li><li><code>atlas.plugin.package-builder</code></li></ul><h2 id="paket" tabindex="-1">Paket <a class="header-anchor" href="#paket" aria-label="Permalink to &quot;Paket&quot;">​</a></h2><p><code>createHomeAssistantCardEditorPluginInstallPackage()</code> erzeugt ein erstes Installpaket für das Referenz-Plugin. Es enthält ein Plugin-Manifest, eine README und ein Beispiel für eine Home-Assistant-Card-Konfiguration.</p><h2 id="beschreibung-im-hub" tabindex="-1">Beschreibung im Hub <a class="header-anchor" href="#beschreibung-im-hub" aria-label="Permalink to &quot;Beschreibung im Hub&quot;">​</a></h2><p>Hub und Administration können lokalisierte Beschreibungen aus dem Plugin-Repository anzeigen. Die gewählte Sprache bevorzugt <code>descriptions.de</code>, <code>descriptions.en</code> oder <code>descriptions.fr</code>, sofern vorhanden. Englisch bleibt der Fallback.</p>',22)])])}const p=t(a,[["render",s]]);export{c as __pageData,p as default};
